def solve_case_3_2():
    solutions = []

    # Step 1: Find pairs (q, r) such that q + r = 800, q < r, q, r are primes.
    # q must be odd (since 800 is even and q, r != 2). q < 400.

    q_candidates = []
    for q in range(3, 400):
        if is_prime(q):
            r = 800 - q
            if r > q and is_prime(r):
                q_candidates.append((q, r))

    print(f"Found {len(q_candidates)} pairs (q, r) summing to 800:")
    # print(q_candidates) # Commented out for brevity, will process iteratively

    # Step 2: For each pair (q, r), search for prime p < q.
    for q, r in q_candidates:
        print(f"\n--- Checking pair (q={q}, r={r}) ---")

        # Iterate over possible primes p < q
        for p in range(2, q):
            if not is_prime(p):
                continue

            # Check constraints:
            # 1. D = p + q + r = p + 800 must be prime
            D = p + 800
            if not is_prime(D):
                continue

            # 2. B = q + r - p = 800 - p must be prime
            B = 800 - p
            if not is_prime(B):
                continue

            # 3. A = p + q - r. Must be prime and > 0.
            A = p + q - r
            if A <= 0 or not is_prime(A):
                # We must ensure p + 2q > 800 for A > 0
                # p + 2q - 800 > 0
                continue

            # 4. C = r + p - q. Must be prime.
            C = r + p - q
            if not is_prime(C):
                continue

            # All conditions met!
            solution = (p, q, r)
            solutions.append(solution)
            print(f"Found solution: p={p}, q={q}, r={r}. Primes are: A={A}, B={B}, C={C}, D={D}")

    return solutions

